INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Manchester City win the 2026-27 English Premier League (EPL) Championship?', 'This market will resolve according to the team that wins the 2026-27 English Premier League (EPL) Championship.

If at any point it becomes impossible for a listed team to win the 2026-27 English Premier League (EPL) Championship per the rules of English Premier League (EPL) (e.g., they are eliminated in the playoffs), the corresponding market will resolve to "No".

If the 2026-27 English Premier League (EPL) season is cancelled, postponed after June 14, 2027, 11:59 PM ET or there is otherwise no winner declared within that timeframe, this market will resolve to "Other".

The primary resolution source will be official information from English Premier League (EPL); however, a consensus of credible reporting may also be used.', 'sports', 'active', 204647.14, 567606.21, 205147.14, 568106.21);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Anthropic have the highest IPO Market Cap 2026?', 'This market will resolve to the company that achieves the highest market capitalization in U.S. dollars based on the official closing price on its first trading day in 2026.

This market will resolve to a company that completes an Initial Public Offering (IPO) between January 1 and December 31, 2026, 11:59 PM ET.

Market capitalization is defined as the total number of outstanding shares multiplied by the closing share price on the first trading day.

If two or more companies have exactly equal highest closing market capitalizations, this market will resolve to the company whose listed name comes first alphabetically.

Resolution will be based on the primary exchange’s official listing page. In the event that the relevant figure is not displayed, another reliable source will be used.

In case the respective company''s primary exchange’s official listing page does not report in U.S. dollars, it will be converted to U.S. dollars using the U.S. Federal Reserve Board’s H.10 foreign exchange reference rate for the relevant currency pair on the company’s first trading day (https://www.federalreserve.gov/releases/h10/). If no such rate is available for the relevant trading day, the most recent previously published rate will be used. If the relevant currency is not listed, another credible exchange rate source will be used.

A listed company may resolve to "No" as soon as it becomes unable to complete an IPO, including due to acquisition, merger, or absorption by an entity that is already publicly traded.

In the event of an interruption in the course of the normal trading session on the respective companies’ first day of trading (e.g., a circuit breaker or half-day), the market will resolve according to the official closing price of the abbreviated session. If no such official closing price is published, the market will resolve according to the next trading day on which an official closing price is published, treating that as the first day of trading for purposes of this market.', 'tech', 'active', 36911.73, 321454.6, 37411.73, 321954.6);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Tyreek Hill play for the Chicago Bears next?', 'This market will resolve to the next NFL team Tyreek Hill joins by August 31, 2026, 11:59 PM ET.

If Tyreek Hill does not join a new NFL team by August 31, 2026, 11:59 PM ET, this market will resolve to “Other”.

If Tyreek Hill joins a team that is not listed, this market will resolve to “Other”.

If Tyreek Hill is released and is not signed by another team, retires, or is not under contract with any NFL team by August 31, 2026, 11:59 PM ET, this market will resolve to “Other”.

Transfers or assignments between a team’s senior team and reserve or affiliate teams will not be considered for this market.

An official signing announcement prior to the market’s close date will immediately resolve this market to the corresponding option.

The resolution source for this market will be official information from the NFL or the acquiring team.', 'sports', 'active', 10967.35, 1085767.36, 11467.35, 1086267.36);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Bitcoin reach $100,000 in August?', 'This market will immediately resolve to "Yes" if any Binance 1 minute candle for BTC/USDT during the month specified in the title (from 00:00 AM ET on the first day to 11:59 PM ET on the last), has a final High price equal to or greater than the price specified in the title. Otherwise, this market will resolve to "No."

The resolution source for this market is Binance, specifically the BTC/USDT High prices available at https://www.binance.com/en/trade/BTC_USDT, with the chart settings on "1m" for one-minute candles selected on the top bar.

Please note that the outcome of this market depends solely on the price data from the Binance BTC/USDT trading pair. Prices from other exchanges, different trading pairs, or spot markets will not be considered for the resolution of this market.', 'crypto', 'active', 2722.99, 269575.75, 3222.99, 270075.75);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('LoL: Bilibili Gaming vs JD Gaming (BO3) - LPL Group Ascend', 'This market refers to the LoL match between Bilibili Gaming and JD Gaming in the LPL Group Ascend, initially scheduled for August 12 at 7:00AM ET.

This market will resolve to "Bilibili Gaming" if Bilibili Gaming win the match against JD Gaming.

This market will resolve to "JD Gaming" if JD Gaming win the match against Bilibili Gaming.

If the match is canceled (not played at all), ends in a tie, or is delayed beyond 7 days from the scheduled date without a winner determined, this market will resolve to 50-50. 

If the match begins but is not completed, and one team wins due to the opponent''s forfeiture, disqualification, or walkover, this market will resolve to the team who wins. 

If the match ends in a forfeit, disqualification, or walkover (team withdraws before the start and the other wins automatically), this market will resolve to 50-50. 

The resolution source for this market will be official information from https://gol.gg/esports/home. However, if https://gol.gg/esports/home has not published final results within 2 hours after the event’s conclusion, a consensus of credible reporting may be used instead including video evidence.

In cases where a team’s listed name includes minor discrepancies from the resolution source, this market will resolve based on the underlying real-world match rather than exact name matching. Recognizable abbreviations, alternate or erroneous spellings, sponsor tags, affiliate or academy designations, regional identifiers, and minor formatting differences will be treated as referring to the same team, provided the intended team can be clearly and uniquely identified within the relevant competition. If a listed team name has no reasonable connection to any participating team, or if it matches or could reasonably refer to another team in the same competition such that the intended team cannot be unambiguously determined, this market will resolve 50-50.', 'sports', 'active', 12227.08, 1210481.22, 12727.08, 1210981.22);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Satoshi move any Bitcoin in 2026?', 'This market will resolve to “Yes” if any wallet labeled as belonging to Satoshi Nakamoto on Arkham’s Intel Explorer shows an “Outflow” or “Swaps” transaction at any time between January 9, 2026, 1:00 PM ET and December 31, 2026, 11:59 PM ET. Otherwise, this market will resolve to “No.”

The resolution source for this market is Arkham’s Intel Explorer, specifically the entity page for Satoshi Nakamoto available at https://intel.arkm.com/explorer/entity/satoshi-nakamoto

If Arkham becomes permanently unavailable, this market will resolve based on a consensus of credible sources.


', 'crypto', 'active', 109837.55, 2252260.2, 110337.55, 2252760.2);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Count Binface win the Clacton by-election?', 'A by-election for the United Kingdom parliamentary constituency of Clacton is expected to be held soon following the announced resignation of incumbent Nigel Farage.

This market will resolve according to the candidate who wins the Clacton parliamentary by-election.

If the election results are not known definitively by June 30, 2027, 11:59 PM ET, this market will resolve to "Other".

The resolution source for this market will be a consensus of credible reporting. In case of ambiguity, this market will resolve solely based on official election results as published by Tendring District Council (https://www.tendringdc.gov.uk/) and the UK Parliament (https://www.parliament.uk/).', 'politics', 'active', 15005.25, 1414066.44, 15505.25, 1414566.44);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Renan Santos finish in second place in the first round of the 2026 Brazilian presidential election?', 'A presidential election is scheduled to take place in Brazil on October 4, 2026.

This market will resolve according to the listed candidate who receives the second-most valid votes in the first round of this election.

The named candidates will be primarily ranked by the number of valid votes received in the specified election. If two or more candidates are tied on valid votes, ties will be broken by alphabetical order of the candidates'' last names. This market will resolve to the candidate that occupies the second-highest finishing position after applying this ranking.

If the result of this election isn''t known definitively by June 30, 2027, 11:59 PM ET, the market will resolve to "Other".

This market will resolve based on the result of the election, as indicated by a consensus of credible reporting. If there is ambiguity, this market will resolve based solely on the official results as reported by the Brazilian government, specifically the Superior Electoral Court (Tribunal Superior Eleitoral, TSE) (e.g., https://dadosabertos.tse.jus.br/).', 'politics', 'active', 47238.22, 502043.43, 47738.22, 502543.43);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Epstein client list released by October 31?', 'This market will resolve to “Yes” if files which were not previously public and which pertain to the illegal activities of Jeffrey Epstein are made public by October 31, 2026, 11:59 PM ET, and those files contain a list of individuals associated with Epstein in connection with his illegal activities, including but not limited to sex trafficking or related crimes. Otherwise, this market will resolve to “No.”

To qualify, the files must contain names in a context equivalent to what is commonly referred to as Epstein’s “client list”—that is, a document that explicitly identifies a list or set of individuals as being directly connected to, participating in, facilitating, funding, soliciting, or otherwise being implicated in Jeffrey Epstein’s illegal activities.

A document may qualify even if it does not contain explicit incriminating language on its face, so long as credible reporting or accompanying official context confirms that the released document is an incriminating client list or functionally equivalent roster of individuals tied to Epstein’s illegal activity.

The following will not qualify:

- Flight logs, passenger manifests, visitor logs, or transportation records which merely show individuals traveling with, meeting with, or visiting Epstein without any explicit or contextual tie to criminal activity.

- Contact books, address lists, social calendars, guest lists, schedules, correspondence logs, or similar documents that include names solely due to social contact, proximity, acquaintance, or logistical interaction with Epstein.

- Any document listing individuals without accompanying language, context, or credible reporting that connects those individuals to Epstein’s illegal activity.

The primary resolution sources for this market will be the released files themselves and a consensus of credible reporting.

Note: References to suspects made internally by the US government over the course of its investigation do not alone constitute a qualifying "client list."', 'politics', 'active', 60, 940, 560, 1440);;